sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);
	
	function TestCase_GetPluginStatus(aWhitelist,vExpected)
	{
		function TestCase_GetPluginStatus_CheckResult(vInput,vExpected,vResult)
		{
			if (vExpected === false)
			{
				return (vResult === false);
			}

			if (vExpected == 'all')
			{
				return (vResult.length > 500);
			}

			var nExpected = x_snc_devtools.GetIntegerValue(vExpected);
			if (vResult.length != nExpected)
			{
				return false;
			}

			return true;
		}
		
		test.TestCase(
			'Function GetPluginStatus()',
			GetPluginStatus,
			{
				'aWhitelist': aWhitelist
			},
			vExpected,
			TestCase_GetPluginStatus_CheckResult);
	}
		
	TestCase_GetPluginStatus(null,false);
	TestCase_GetPluginStatus([],false);

	var aWhitelistSysIds = [];
	var aWhitelistIds = [];
	var aWhitelistNames = [];
	var aWhitelistMixed = [];

	var grPlugin = new GlideRecord('sys_plugins');
	grPlugin.setLimit(5);
	grPlugin.query();
	var nMixed = 0;
	while (grPlugin.next())
	{
		aWhitelistSysIds.push(x_snc_devtools.GetStringValue(grPlugin.sys_id));
		aWhitelistIds.push(x_snc_devtools.GetStringValue(grPlugin.source));
		aWhitelistNames.push(x_snc_devtools.GetStringValue(grPlugin.name));

		if (nMixed == 0)
		{
			aWhitelistMixed.push(x_snc_devtools.GetStringValue(grPlugin.sys_id));
		}
		else if (nMixed == 1)
		{
			aWhitelistMixed.push(x_snc_devtools.GetStringValue(grPlugin.source));
		}
		else if (nMixed == 2)
		{
			aWhitelistMixed.push(x_snc_devtools.GetStringValue(grPlugin.name));
		}		

		nMixed++;
		if (nMixed == 3)
		{
			nMixed = 0;
		}
	}

	TestCase_GetPluginStatus(aWhitelistSysIds,5);
	TestCase_GetPluginStatus(aWhitelistIds,5);
	TestCase_GetPluginStatus(aWhitelistNames,5);
	TestCase_GetPluginStatus(aWhitelistMixed,5);

	TestCase_GetPluginStatus(['all'],'all');	
	
	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
